# 13_figure.R: multipanel simulation figure (plotting only; reads revision_sim/tables). Run from final/.
# A simulated niches and guild dominance (Simulation B); B known / independently estimated (Monte Carlo) response surfaces; C errors (estimate - truth) of spread-only, additive and interaction fits (replicate means over cells supported in >= 50% of replicates; identical support for all models);
# D paired held-out gain of the explicit interaction over the additive model (median and central 95% interval over 50 replicates; weak (1e-6, solid) and empirical-default (5e-3, dashed) endpoint shrinkage).
suppressPackageStartupMessages({library(ggplot2); library(dplyr); library(tidyr); library(patchwork); library(scales)}); stopifnot(requireNamespace("svglite", quietly = TRUE)); IN <- "revision_sim/tables"; OUTF <- "revision_sim/figures"
ink <- "#252B2D"; petrol <- "#246878"; orange <- "#C45C19"; sage <- "#79936C"; purple <- "#615A83"; grey <- "#848B8D"; grid_col <- "#E5E9E9"
base <- theme_minimal(base_size = 8.5, base_family = "sans") + theme(text = element_text(colour = ink), axis.text = element_text(size = 6.8, colour = ink), axis.title = element_text(size = 7.6, colour = ink), axis.line = element_line(colour = ink, linewidth = .3), axis.ticks = element_line(colour = ink, linewidth = .25), axis.ticks.length = unit(1, "mm"),
  panel.grid.major = element_line(colour = grid_col, linewidth = .25), panel.grid.minor = element_blank(), panel.spacing = unit(2, "mm"), strip.background = element_blank(), strip.text = element_text(size = 6.8, face = "bold", colour = ink), legend.position = "bottom", legend.title = element_blank(), legend.text = element_text(size = 6.8), legend.key.height = unit(2.5, "mm"), legend.key.width = unit(6, "mm"), legend.margin = margin(0, 0, 0, 0), legend.box.spacing = unit(1, "mm"), plot.tag = element_text(size = 11, face = "bold"), plot.margin = margin(2, 3, 1, 2))
# ---- A
nic <- read.csv(file.path(IN, "simB_niche_curves.csv")); dom <- read.csv(file.path(IN, "simB_guild_dominance.csv"))
pA1 <- ggplot(nic, aes(x, niche, group = species, colour = guild)) + geom_line(linewidth = .2, alpha = .35) + scale_colour_manual(values = c(specialist = petrol, generalist = orange)) + labs(tag = "A", x = "Productivity gradient", y = "Niche (relative suitability)") + base + guides(colour = guide_legend(override.aes = list(linewidth = .8, alpha = 1)))
pA2 <- ggplot(dom, aes(x, generalist_dominance, colour = scenario, linetype = scenario)) + geom_line(linewidth = .8) + scale_colour_manual(values = c(logistic = purple, control = grey), labels = c(logistic = "Logistic dominance shift", control = "Control (constant)")) + scale_linetype_manual(values = c(logistic = "solid", control = "42"), labels = c(logistic = "Logistic dominance shift", control = "Control (constant)")) + scale_y_continuous(limits = c(0, 1)) + labs(x = "Productivity gradient", y = "Generalist share of individuals") + base
# ---- B/C surfaces
lab_src <- c(A_strong = "A strong (known)", B_logistic = "B logistic (MC)", B_control = "B control (MC)")
SA <- read.csv(file.path(IN, "simA_surfaces.csv")) |> filter(scenario == "strong", order %in% c(2, 5)) |> mutate(source = "A_strong", response = "known"); SB <- read.csv(file.path(IN, "simB_surfaces.csv")) |> filter(response == "relative", order %in% c(2, 5)) |> mutate(source = paste0("B_", scenario))
S <- bind_rows(SA, SB) |> filter(config %in% c("spread_only", "additive", "interaction_1e-06"))
agg <- S |> group_by(source, order, config, m_std, h_std) |> summarise(n_sup = sum(supported), est = mean(resp_est[supported]), truth = mean(resp_true), .groups = "drop") |> mutate(est = ifelse(n_sup >= 25, est, NA), err = est - truth, truth = ifelse(n_sup >= 25, truth, NA)); write.csv(agg, file.path(OUTF, "Figure_simulation_BC_plotted_surfaces.csv"), row.names = FALSE)
tile <- function(d, fill, pal) ggplot(d, aes(m_std, h_std, fill = .data[[fill]])) + geom_tile(colour = "white", linewidth = .1) + pal + scale_x_continuous(breaks = c(-1, 0, 1)) + scale_y_continuous(breaks = c(.8, 1.6, 2.4)) + base + theme(legend.position = "right", legend.key.height = unit(8, "mm"), legend.key.width = unit(2.5, "mm"), panel.grid = element_blank(), axis.title.y = element_text(size = 7))
seqpal <- scale_fill_gradient(low = "white", high = petrol, na.value = "#EEF0F0", name = "Truth", limits = c(0, 1)); divpal <- scale_fill_gradient2(low = petrol, mid = "white", high = orange, midpoint = 0, na.value = "#EEF0F0", name = "Estimate -\ntruth", limits = c(-.2, .2), oob = squish)
tb <- agg |> filter(config == "additive") |> mutate(col = factor(paste0(lab_src[source], ", k = ", order), unique(paste0(rep(lab_src, each = 2), ", k = ", c(2, 5)))))
pB <- tile(tb, "truth", seqpal) + facet_wrap(~col, nrow = 1, labeller = labeller(col = label_wrap_gen(16))) + labs(tag = "B", x = "Position (gradient SD units)", y = "Spread") + theme(strip.text = element_text(size = 6.2))
tc <- agg |> filter(source != "B_control") |> mutate(col = factor(paste0(lab_src[source], ", k = ", order), unique(paste0(rep(lab_src[c(1, 2)], each = 2), ", k = ", c(2, 5)))), model = factor(config, c("spread_only", "additive", "interaction_1e-06"), c("Spread-only", "Additive", "Interaction")))
pC <- tile(tc, "err", divpal) + facet_grid(model ~ col, labeller = labeller(col = label_wrap_gen(16))) + labs(tag = "C", x = "Position (gradient SD units)", y = "Spread") + theme(strip.text = element_text(size = 6.2))
# ---- D
gA <- read.csv(file.path(IN, "simA_summary_gains.csv")) |> filter(grepl("minus additive", contrast), grepl("^interaction", contrast)) |> mutate(panel = "A: known parameters", series = scenario); gB <- read.csv(file.path(IN, "simB_summary_gains.csv")) |> filter(grepl("minus additive", contrast), grepl("^interaction", contrast), response %in% c("incidence", "relative")) |> mutate(panel = paste0("B: ", ifelse(response == "incidence", "incidence", "relative abundance")), series = scenario)
G <- bind_rows(gA, gB) |> mutate(shrink = ifelse(grepl("1e-06", contrast), "weak shrinkage (1e-6)", ifelse(grepl("5e-03", contrast), "default shrinkage (5e-3)", "1e-4")), panel = factor(panel, unique(panel))) |> filter(shrink != "1e-4"); write.csv(G, file.path(OUTF, "Figure_simulation_D_plotted_gains.csv"), row.names = FALSE)
pal <- c(none = grey, moderate = sage, strong = orange, logistic = purple, control = grey)
pD <- ggplot(G, aes(order, median, colour = series, linetype = shrink)) + geom_hline(yintercept = 0, colour = "#A2AAAC", linewidth = .3) + geom_linerange(data = G |> filter(shrink == "weak shrinkage (1e-6)"), aes(ymin = q025, ymax = q975), linewidth = .35, alpha = .5, position = position_dodge(width = .5), show.legend = FALSE) + geom_line(linewidth = .6, position = position_dodge(width = .5)) + geom_point(data = G |> filter(shrink == "weak shrinkage (1e-6)"), size = 1.1, position = position_dodge(width = .5)) +
  facet_wrap(~panel, nrow = 1, scales = "free_y") + scale_colour_manual(values = pal, labels = c(none = "A: none", moderate = "A: moderate", strong = "A: strong", logistic = "B: logistic", control = "B: control")) + scale_linetype_manual(values = c("weak shrinkage (1e-6)" = "solid", "default shrinkage (5e-3)" = "42")) + scale_x_continuous(breaks = c(2, 3, 4, 5, 8)) + labs(tag = "D", x = "Zeta order, k", y = expression("Paired held-out " * Delta * D^2 * " (interaction - additive)")) + base + theme(legend.box = "vertical")
fig <- ((pA1 | pA2) / pB / pC / pD) + plot_layout(heights = c(.85, .8, 1.6, 1.15))
for (ext in c("pdf", "svg", "png")) ggsave(file.path(OUTF, paste0("Figure_simulation_interaction.", ext)), fig, width = 183, height = 235, units = "mm", dpi = 600, bg = "white", device = switch(ext, pdf = grDevices::cairo_pdf, svg = svglite::svglite, png = "png"))
# Notes: B/C axes are matched-profile position (x, standardised units of the gradient) and spread (y, standardised units); C is the replicate-mean estimate minus truth on the response scale; cells unsupported in >= 50% of replicates are grey. Truth in B: A known parameters; B Monte Carlo of the generative community model (no fitted model).
